   from public.reservations x where (op='create' or x.id<>r.id)
    and coalesce(x.status,'') not in ('cancelled','completed','pending-refund')
    and (x.date+x."timeSlot"::time)<ends and (x.date+x."timeSlot"::time+x."durationHours"*interval '1 hour')>begins
  ), changes as (
   select starts_at as at_time,1 as delta from intervals union all select ends_at,-1 from intervals
  ), grouped as (select at_time,sum(delta) as delta from changes group by at_time),
  occupancy as (select at_time,sum(delta) over(order by at_time rows unbounded preceding) as used from grouped)
  select coalesce(max(used),0) into peak_occupied from occupancy where at_time<ends;
  if peak_occupied>=maximum then raise exception 'ONLINE_CAPACITY'; end if;
  if op='create' then
   if length(trim(coalesce(cfg->>'termsAndConditions','')))=0 then raise exception 'CONFIG_TERMS_REQUIRED'; end if;
   if p->'acceptedTerms' is distinct from 'true'::jsonb or p->>'expectedTerms' is distinct from cfg->>'termsAndConditions' then raise exception 'TERMS_CHANGED'; end if;
   if length(trim(coalesce(p->>'customerName','')))<2 or length(p->>'customerName')>120 or coalesce(p->>'contactNumber','') !~ '^\+?[0-9][0-9 -]{6,24}$' then raise exception 'INVALID_CONTACT'; end if;
   rate:=(cfg->>'hourlyRate')::numeric;
   if rate is null or rate<0 or rate>100000 or rate*100<>trunc(rate*100) or (cfg->>'downPaymentPercent') is null or (cfg->>'downPaymentPercent')::numeric not between 0 and 100 then raise exception 'CONFIG_INVALID'; end if;
   base_cents:=(rate*100)::bigint*duration;
   promo_code:=nullif(upper(trim(coalesce(p->>'promoCode',''))),'');
   if promo_code is not null then
    if (select count(*) from public.promo_codes where upper(code)=promo_code)<>1 then raise exception 'PROMO_UNAVAILABLE'; end if;
    select * into promo from public.promo_codes where upper(code)=promo_code for update;
    if not found or promo.is_active is distinct from true or promo.discount_percent is null or promo.discount_percent<=0 or promo.discount_percent>100 or (promo.start_date is not null and promo.start_date>statement_timestamp()) or (promo.expires_at is not null and promo.expires_at<=statement_timestamp()) or (coalesce(promo.is_limited_uses,false) and (promo.max_usage is null or coalesce(promo.usage_count,0)>=promo.max_usage)) then raise exception 'PROMO_UNAVAILABLE'; end if;
    discount_cents:=floor(base_cents*promo.discount_percent::numeric/10000)*100;
   end if;
   total_cents:=base_cents-discount_cents; dp_cents:=least(total_cents,ceil(total_cents*(cfg->>'downPaymentPercent')::numeric/10000)*100);
   if (p->>'expectedTotalCents')::bigint is distinct from total_cents or (p->>'expectedDownPaymentCents')::bigint is distinct from dp_cents then
    raise exception 'QUOTE_CHANGED' using detail=jsonb_build_object('totalCents',total_cents,'downPaymentCents',dp_cents,'discountCents',discount_cents)::text;
   end if;
   receipt_path:=nullif(p->>'receiptPath','');
   if dp_cents>0 and (receipt_path is null and length(trim(coalesce(p->>'paymentRef','')))<3) then raise exception 'PAYMENT_EVIDENCE_REQUIRED'; end if;
   if length(coalesce(p->>'paymentRef',''))>120 then raise exception 'INVALID_PAYMENT_REFERENCE'; end if;
   if receipt_path is not null then
    if receipt_path !~ ('^'||uid::text||'/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\.(jpg|png)$') or not exists(select 1 from storage.objects where bucket_id='oneshot-receipts' and name=receipt_path and owner_id=uid::text for share) then raise exception 'RECEIPT_NOT_OWNED'; end if;
    if exists(select 1 from public.reservations where "receiptImg"=receipt_path) then raise exception 'RECEIPT_ALREADY_USED'; end if;
   end if;
   insert into public.reservations(id,"customerName","contactNumber",email,date,"timeSlot","durationHours","partySize","tableId",status,"totalAmount","downPaymentAmount","downPaymentPaid",balancepaid,"balancePaid",promocode,"promoCode","discountAmount","createdAt","receiptImg","paymentRef","rescheduleCount",customer_user_id,revision,total_amount_cents,down_payment_amount_cents,discount_amount_cents)
   values(gen_random_uuid()::text,trim(p->>'customerName'),trim(p->>'contactNumber'),account_email,d,to_char(tm,'HH24:MI'),duration,party,table_id,'pending',total_cents::numeric/100,dp_cents::numeric/100,0,0,0,promo_code,promo_code,discount_cents::numeric/100,statement_timestamp(),receipt_path,nullif(trim(p->>'paymentRef'),''),0,uid,1,total_cents,dp_cents,discount_cents) returning * into r;
   if promo_code is not null then update public.promo_codes set usage_count=coalesce(usage_count,0)+1 where id=promo.id; end if;
  else
   update public.reservations set date=d,"timeSlot"=to_char(tm,'HH24:MI'),"rescheduleCount"=coalesce("rescheduleCount",0)+1,revision=revision+1 where id=r.id returning * into r;
  end if;
 end if;
 operation_result:=jsonb_build_object('reservation',to_jsonb(r)||jsonb_build_object('totalAmount',r.total_amount_cents::numeric/100,'downPaymentAmount',r.down_payment_amount_cents::numeric/100,'discountAmount',r.discount_amount_cents::numeric/100),'replayed',false);
 insert into oneshot_private.booking_operations(customer_user_id,request_id,operation,payload,result) values(uid,req,op,p,operation_result);
 return operation_result;
end $$;
revoke all on function oneshot_private.booking_command(text,jsonb) from public,anon,authenticated;
grant execute on function oneshot_private.booking_command(text,jsonb) to authenticated;
create or replace function public.oneshot_booking_create(payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select oneshot_private.booking_command('create',payload)$$;
create or replace function public.oneshot_booking_reschedule(payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select oneshot_private.booking_command('reschedule',payload)$$;
create or replace function public.oneshot_booking_cancel(payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select oneshot_private.booking_command('cancel',payload)$$;
revoke all on function public.oneshot_booking_create(jsonb),public.oneshot_booking_reschedule(jsonb),public.oneshot_booking_cancel(jsonb) from public,anon,authenticated;
grant execute on function public.oneshot_booking_create(jsonb),public.oneshot_booking_reschedule(jsonb),public.oneshot_booking_cancel(jsonb) to authenticated;
-- Require the matching containment policy cutover: direct client writes remain forbidden.
revoke insert,update,delete,truncate,references,trigger,maintain on public.reservations from public,anon,authenticated;

-- SOURCE booking-availability.draft.sql SHA256 d4b98cff87dfe87df47c9b79cd155f6e7befc3609afdb22f307ef0369f6ab150
-- Coordinated customer cutover candidate. Never apply independently of its caller migration.

SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '10s';
DO $$ BEGIN
  IF current_setting('oneshot.secure_gateway_cutover', true) IS DISTINCT FROM 'reviewed' THEN
    RAISE EXCEPTION 'Stop: review and coordinate the secure customer cutover first';
  END IF;
END $$;
CREATE SCHEMA IF NOT EXISTS oneshot_private;
REVOKE ALL ON SCHEMA oneshot_private FROM PUBLIC;
GRANT USAGE ON SCHEMA oneshot_private TO anon, authenticated;
CREATE OR REPLACE FUNCTION oneshot_private.availability(p_from date, p_to date)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  today date := (statement_timestamp() AT TIME ZONE 'Asia/Manila')::date;
  announcement_rows jsonb := '[]'; cms_rows jsonb := '{}';
  table_rows jsonb := '[]'; busy_rows jsonb := '[]'; settings_rows jsonb := '[]';
  configuration_issues jsonb := '[]';
  closure_rows jsonb := '[]'; promo_rows jsonb := '[]'; event_rows jsonb := '[]';
  t record; s jsonb; active boolean; safe_status text;
  cfg jsonb; setting_key text; raw text; value numeric; minimum numeric; maximum numeric; prefix text;
  capacity_valid boolean:=true; party_valid boolean:=true; pricing_valid boolean:=true; hours_valid boolean:=true;
BEGIN
  IF p_from IS NULL OR p_to IS NULL OR p_from < today - 1 OR p_to < p_from OR p_to - p_from > 31 OR p_to > today + 90 THEN
    RAISE EXCEPTION 'Availability requires a valid range of at most 31 days within the next 90 days' USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(*) FROM public.tables) > 500 THEN
    RAISE EXCEPTION 'Availability configuration needs review';
  END IF;
  FOR t IN SELECT id,name,status,isactive,"isActive",sessiondata,"sessionData" FROM public.tables ORDER BY id LOOP
    active := t.isactive = 1 AND t."isActive" = 1;
    safe_status := CASE WHEN t.status IN ('available','occupied','reserved','maintenance','event') THEN t.status ELSE 'maintenance' END;
    s := NULL;
    -- Legacy aliases must agree. Invalid or open-ended sessions block the table without leaking their contents.
    IF t.sessiondata IS NOT NULL AND t."sessionData" IS NOT NULL AND t.sessiondata IS DISTINCT FROM t."sessionData" THEN
      active := false; safe_status := 'maintenance';
    ELSIF COALESCE(t.sessiondata,t."sessionData") IS NOT NULL THEN
      BEGIN
        s := COALESCE(t.sessiondata,t."sessionData")::jsonb;
        IF s->>'kind'='trusted-native-move-hold' AND safe_status='reserved' THEN
          active:=false;s:=NULL;
        ELSIF s='null'::jsonb OR s='{}'::jsonb THEN
          s:=NULL;
          IF safe_status='occupied' THEN active:=false; safe_status:='maintenance'; END IF;
        ELSIF jsonb_typeof(s) <> 'object' OR NOT (s ? 'startTime') OR (s->>'isOpenTime')::boolean IS DISTINCT FROM false
          OR (s->>'durationMinutes')::numeric <= 0 OR (s->>'durationMinutes')::numeric > 1440
          OR s->>'durationMinutes' IS NULL OR s->>'startTime' IS NULL THEN
          active := false; safe_status := 'maintenance'; s := NULL;
        ELSE
          PERFORM (s->>'startTime')::timestamptz;
          s := jsonb_build_object('startTime',s->>'startTime','durationMinutes',(s->>'durationMinutes')::numeric,'isOpenTime',false);
        END IF;
      EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN
        active := false; safe_status := 'maintenance'; s := NULL;
      END;
    ELSIF safe_status = 'occupied' THEN
      active := false; safe_status := 'maintenance';
    END IF;
    IF safe_status IN ('occupied','event') THEN active := false; END IF;
    table_rows := table_rows || jsonb_build_array(jsonb_build_object('id',t.id,'name',t.name,'status',safe_status,'isActive',COALESCE(active,false),'session',s));
  END LOOP;
  IF EXISTS (SELECT 1 FROM public.reservations WHERE date IS NULL AND COALESCE(status,'') NOT IN ('cancelled','completed','pending-refund')) THEN
    RAISE EXCEPTION 'Availability contains an unresolved booking date';
  END IF;
  IF (SELECT count(*) FROM public.reservations WHERE date BETWEEN p_from - 1 AND p_to AND COALESCE(status,'') NOT IN ('cancelled','completed','pending-refund')) > 5000 THEN
    RAISE EXCEPTION 'Availability volume requires a smaller range';
  END IF;
  IF EXISTS (SELECT 1 FROM public.reservations WHERE date BETWEEN p_from - 1 AND p_to AND COALESCE(status,'') NOT IN ('cancelled','completed','pending-refund')
    AND ("timeSlot" IS NULL OR "timeSlot" !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' OR "durationHours" IS NULL OR "durationHours" NOT BETWEEN 1 AND 24 OR "tableId" IS NULL)) THEN
    RAISE EXCEPTION 'Availability contains an unresolved booking interval';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('tableId',"tableId",'date',date,'timeSlot',"timeSlot",'durationHours',"durationHours",'status','confirmed') ORDER BY date,"timeSlot"),'[]')
    INTO busy_rows FROM public.reservations WHERE date BETWEEN p_from - 1 AND p_to AND COALESCE(status,'') NOT IN ('cancelled','completed','pending-refund');
  SELECT COALESCE(jsonb_agg(jsonb_build_object('key_name',key_name,'setting_value',setting_value) ORDER BY key_name),'[]') INTO settings_rows
  FROM public.system_settings WHERE key_name IN (
    'hourlyRate','overtimeRate','downPaymentPercent','bookingCutoffMinutes','weekdayStartTime','weekdayEndTime','weekendStartTime','weekendEndTime',
    'isWeekdayHappyHourActive','weekdayHappyHourRate','weekdayHappyHourStart','weekdayHappyHourEnd','isWeekendHappyHourActive','weekendHappyHourRate',
    'weekendHappyHourStart','weekendHappyHourEnd','weekdayOnlineCapacityLimit','weekendOnlineCapacityLimit','minHours','maxHours','cancellationHours',
    'advanceBookingHours','bookingCapacityMode','weekdayMinPartySize','weekdayMaxPartySize','weekendMinPartySize','weekendMaxPartySize','cancellationPolicy','termsAndConditions');
  IF (SELECT count(*) FROM public.closed_dates WHERE (type = 'weekly' OR closed_date BETWEEN p_from - 1 AND p_to) AND status IS DISTINCT FROM 'cancelled' AND cancelled_at IS NULL) > 500 THEN
    RAISE EXCEPTION 'Closure configuration requires review';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'date',closed_date,'reason',reason,'isFullDay',is_full_day,'openTime',open_time,'closeTime',close_time,'type',type,'dayOfWeek',day_of_week)),'[]')
    INTO closure_rows FROM public.closed_dates WHERE (type = 'weekly' OR closed_date BETWEEN p_from - 1 AND p_to) AND status IS DISTINCT FROM 'cancelled' AND cancelled_at IS NULL;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'code',code,'discountPercent',discount_percent,'description',description,'isActive',is_active,
    'isLimitedUses',is_limited_uses,'exhausted',is_limited_uses AND COALESCE(usage_count,0) >= COALESCE(max_usage,0),'startDate',start_date,'expiresAt',expires_at)),'[]')
    INTO promo_rows FROM public.promo_codes WHERE is_active = true AND (expires_at IS NULL OR expires_at > statement_timestamp()) AND (start_date IS NULL OR start_date <= statement_timestamp());
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'title',title,'date',date,'type',type,'description',description,'allowReservations',allowreservations=1,
    'caterWalkIns',caterwalkins=1,'walkInTableCount',walkintablecount)),'[]') INTO event_rows FROM public.events WHERE date BETWEEN p_from - 1 AND p_to
    AND COALESCE(iscancelled,0)=0 AND status IS DISTINCT FROM 'cancelled' AND cancelled_at IS NULL;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'title',title,'content',content,'type',type,'isActive',true,'createdAt',createdat,'expiresAt',expiresat)),'[]')
    INTO announcement_rows FROM public.announcements WHERE isactive=1 AND (expiresat IS NULL OR expiresat>statement_timestamp());
  SELECT COALESCE(jsonb_object_agg(keyname,settingvalue),'{}') INTO cms_rows FROM public.cms WHERE keyname IN ('heroImages','aboutImage');
  SELECT COALESCE(jsonb_object_agg(entry.value->>'key_name',entry.value->>'setting_value'),'{}')
    INTO cfg FROM jsonb_array_elements(settings_rows) AS entry(value);
  FOREACH setting_key IN ARRAY ARRAY['weekdayOnlineCapacityLimit','weekendOnlineCapacityLimit'] LOOP
    raw:=btrim(cfg->>setting_key);
    IF raw IS NULL OR length(raw)>64 OR raw!~'^[0-9]+([.][0-9]+)?$' THEN
      capacity_valid:=false;
    ELSE
      value:=raw::numeric;
      IF value<0 OR value>9007199254740991 OR value<>trunc(value) THEN capacity_valid:=false; END IF;
    END IF;
  END LOOP;
  FOREACH prefix IN ARRAY ARRAY['weekday','weekend'] LOOP
    minimum:=NULL; maximum:=NULL;
    raw:=btrim(cfg->>(prefix||'MinPartySize'));
    IF raw IS NOT NULL AND length(raw)<=64 AND raw~'^[0-9]+([.][0-9]+)?$' THEN minimum:=raw::numeric; END IF;
    raw:=btrim(cfg->>(prefix||'MaxPartySize'));
    IF raw IS NOT NULL AND length(raw)<=64 AND raw~'^[0-9]+([.][0-9]+)?$' THEN maximum:=raw::numeric; END IF;
    IF minimum IS NULL OR maximum IS NULL OR minimum<1 OR maximum<minimum OR minimum>9007199254740991 OR maximum>9007199254740991
      OR minimum<>trunc(minimum) OR maximum<>trunc(maximum) THEN party_valid:=false; END IF;
  END LOOP;
  FOREACH setting_key IN ARRAY ARRAY['hourlyRate','downPaymentPercent'] LOOP
    raw:=btrim(cfg->>setting_key);
    BEGIN
      IF raw IS NULL OR raw='' OR length(raw)>64 THEN pricing_valid:=false;
      ELSE
        value:=raw::numeric;
        IF value<0 OR (setting_key='hourlyRate' AND (value>100000 OR value*100<>trunc(value*100)))
          OR (setting_key='downPaymentPercent' AND value>100) THEN pricing_valid:=false; END IF;
      END IF;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN pricing_valid:=false;
    END;
  END LOOP;
  FOREACH setting_key IN ARRAY ARRAY['weekdayStartTime','weekdayEndTime','weekendStartTime','weekendEndTime'] LOOP
    IF cfg->>setting_key IS NULL OR cfg->>setting_key!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN hours_valid:=false; END IF;
  END LOOP;
  IF NOT capacity_valid THEN configuration_issues:=configuration_issues||jsonb_build_array('CONFIG_CAPACITY_LIMITS_REQUIRED'); END IF;
  IF NOT party_valid THEN configuration_issues:=configuration_issues||jsonb_build_array('CONFIG_PARTY_BOUNDS_REQUIRED'); END IF;
  IF NOT pricing_valid THEN configuration_issues:=configuration_issues||jsonb_build_array('CONFIG_PRICING_REQUIRED'); END IF;
  IF NOT hours_valid THEN configuration_issues:=configuration_issues||jsonb_build_array('CONFIG_OPERATING_HOURS_REQUIRED'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public.system_settings WHERE key_name='termsAndConditions' AND length(trim(setting_value)) > 0) THEN
    configuration_issues := configuration_issues || '"CONFIG_TERMS_REQUIRED"'::jsonb;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.system_settings WHERE key_name='bookingCapacityMode' AND setting_value='tables') THEN
    configuration_issues := configuration_issues || '"CONFIG_CAPACITY_REVIEW_REQUIRED"'::jsonb;
  END IF;
  RETURN jsonb_build_object('queueSummary',jsonb_build_object('waitingCount',(SELECT count(*) FROM public.queue WHERE status='waiting')),'announcements',announcement_rows,'cms',cms_rows,'bookingReady',jsonb_array_length(configuration_issues)=0,'configurationIssues',configuration_issues,'version',1,'tables',table_rows,'busy',busy_rows,'settings',settings_rows,'closedDates',closure_rows,'promos',promo_rows,'events',event_rows);
END $$;
REVOKE ALL ON FUNCTION oneshot_private.availability(date,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION oneshot_private.availability(date,date) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.oneshot_booking_availability(p_from date,p_to date)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$ SELECT oneshot_private.availability(p_from,p_to) $$;
REVOKE ALL ON FUNCTION public.oneshot_booking_availability(date,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.oneshot_booking_availability(date,date) TO anon,authenticated;

-- SOURCE staff-identity.draft.sql SHA256 de03de8516c315689f7a888fb0fc840594b67101fbf21fa6095957087bab30fb
-- REVIEW DRAFT: apply after customer-identity and private-receipts candidates.
-- Cloud staff enrollment is an owner-controlled operation, never customer signup.

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='10s';
DO $$ BEGIN
  IF current_setting('oneshot.secure_gateway_cutover',true) IS DISTINCT FROM 'reviewed' THEN
    RAISE EXCEPTION 'Stop: review and coordinate the secure staff cutover first';
  END IF;
  IF to_regprocedure('oneshot_private.verified_customer()') IS NULL THEN
    RAISE EXCEPTION 'Stop: reviewed customer identity guard required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid='storage.objects'::regclass AND polname='receipt_read_guard') THEN
    RAISE EXCEPTION 'Stop: reviewed private receipt policies required';
  END IF;
END $$;

CREATE TEMPORARY TABLE oneshot_staff_memberships_expected (
  user_id uuid PRIMARY KEY,
  venue_id text NOT NULL DEFAULT 'oneshot' CHECK (venue_id='oneshot'),
  role text NOT NULL CHECK (role IN ('cashier','manager')),
  active boolean NOT NULL DEFAULT false,
  approved_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (NOT active OR approved_by IS NOT NULL)
) ON COMMIT DROP;
CREATE TABLE IF NOT EXISTS oneshot_private.staff_memberships (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id),
  venue_id text NOT NULL DEFAULT 'oneshot' CHECK (venue_id='oneshot'),
  role text NOT NULL CHECK (role IN ('cashier','manager')),
  active boolean NOT NULL DEFAULT false,
  approved_by uuid REFERENCES auth.users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (NOT active OR approved_by IS NOT NULL)
);
-- Reapplication never resets authoritative membership rows. Compare the actual
-- authorization table to the same typed/constraint definition before accepting it.
DO $$
DECLARE actual_oid oid;
  expected_oid oid:='pg_temp.oneshot_staff_memberships_expected'::regclass;
  shapes jsonb; column_name text;
BEGIN
  LOCK TABLE oneshot_private.staff_memberships IN ACCESS EXCLUSIVE MODE;
  actual_oid:='oneshot_private.staff_memberships'::regclass;
  IF (SELECT relkind FROM pg_class WHERE oid=actual_oid)<>'r' THEN
    RAISE EXCEPTION 'Stop: incompatible existing staff membership relation';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_inherits WHERE inhrelid=actual_oid OR inhparent=actual_oid) THEN
    RAISE EXCEPTION 'Stop: incompatible existing staff membership inheritance';
  END IF;
  WITH targets AS (SELECT unnest(ARRAY[actual_oid,expected_oid]) AS target_oid),
  definitions AS (
    SELECT t.target_oid,jsonb_build_object(
      'relation',(SELECT jsonb_build_array(c.relkind,c.relowner,c.relispartition)
        FROM pg_class c WHERE c.oid=t.target_oid),
      'columns',(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,a.atttypid,a.atttypmod,
          a.attnotnull,a.attidentity,a.attgenerated,a.attcollation,a.attacl,a.attinhcount,a.attislocal,pg_get_expr(d.adbin,d.adrelid,false)) ORDER BY a.attnum)
        FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
        WHERE a.attrelid=t.target_oid AND a.attnum>0 AND NOT a.attisdropped),
      'constraints',(SELECT jsonb_agg(jsonb_build_array(c.contype,pg_get_constraintdef(c.oid,false),
          c.convalidated,c.condeferrable,c.condeferred,c.connoinherit,c.conislocal,c.coninhcount)
          ORDER BY c.contype,pg_get_constraintdef(c.oid,false))
        FROM pg_constraint c WHERE c.conrelid=t.target_oid AND c.contype<>'f'),
      'customTriggers',(SELECT count(*) FROM pg_trigger g WHERE g.tgrelid=t.target_oid AND NOT g.tgisinternal),
      'rules',(SELECT count(*) FROM pg_rewrite r WHERE r.ev_class=t.target_oid)
    ) AS shape FROM targets t
  ) SELECT jsonb_object_agg(target_oid::text,shape) INTO shapes FROM definitions;
  -- PostgreSQL temporary tables cannot reference permanent auth.users. Check
  -- the two foreign keys separately against their exact authoritative target.
  IF (SELECT count(*) FROM pg_constraint WHERE conrelid=actual_oid AND contype='f')<>2 THEN
    RAISE EXCEPTION 'Stop: incompatible existing staff membership foreign keys';
  END IF;
  FOREACH column_name IN ARRAY ARRAY['user_id','approved_by'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid=actual_oid AND c.contype='f'
      AND c.conkey=ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid=actual_oid AND attname=column_name)]::smallint[]
      AND c.confrelid='auth.users'::regclass
      AND c.confkey=ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid='auth.users'::regclass AND attname='id')]::smallint[]
      AND c.convalidated AND NOT c.condeferrable AND NOT c.condeferred
      AND c.confupdtype='a' AND c.confdeltype='a' AND c.confmatchtype='s'
      AND c.conislocal AND c.coninhcount=0) THEN
      RAISE EXCEPTION 'Stop: incompatible existing staff membership foreign keys';
    END IF;
  END LOOP;
  IF shapes->actual_oid::text IS DISTINCT FROM shapes->expected_oid::text
    OR (SELECT relpersistence FROM pg_class WHERE oid=actual_oid)<>'p' THEN
    RAISE EXCEPTION 'Stop: incompatible existing staff membership table; review schema before reapplying';
  END IF;
END $$;
ALTER TABLE oneshot_private.staff_memberships ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE oneshot_private.staff_memberships FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION oneshot_private.staff_role()
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  SELECT m.role FROM oneshot_private.staff_memberships AS m
  WHERE m.user_id=(SELECT auth.uid()) AND m.venue_id='oneshot' AND m.active
    AND m.approved_by IS NOT NULL AND (SELECT oneshot_private.verified_customer());
$$;
REVOKE ALL ON FUNCTION oneshot_private.staff_role() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION oneshot_private.staff_role() TO authenticated;

CREATE OR REPLACE FUNCTION oneshot_private.verified_staff()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  SELECT oneshot_private.staff_role() IS NOT NULL;
$$;
REVOKE ALL ON FUNCTION oneshot_private.verified_staff() FROM PUBLIC,anon,authenticated;
