 END IF;
END $$;
CREATE SCHEMA IF NOT EXISTS oneshot_private;
REVOKE ALL ON SCHEMA oneshot_private FROM PUBLIC;
GRANT USAGE ON SCHEMA oneshot_private TO authenticated;
